            "타이레놀 먹고 맥주 한 캔 마셨다면, 이건 단순 주의가 아니에요.\n\n소화성궤양, 심한 혈액 이상, 간장애, 신장(콩팥)장애, 심장기능저하 환자, 아스피린 천식 환자, 알코올을 복용한 사람, 만 12세 미만 소아는 이 약을 복용하면 안 돼요. 복용 중에는 음주를 피해야 해요.\n\n간장애·신장장애·소화성궤양 경험자, 고령자(노인), 임부·수유부는 의사 또는 약사와 상의한 뒤 복용하세요. 임신 중 아세트아미노펜이 상대적으로 안전하다는 건 맞지만, 자의적 판단보다 상담이 먼저예요. 고령자는 신장 기능이 떨어져 있어 약이 체내에 오래 남을 수 있어서 용량을 줄이거나 복용 간격을 늘려야 할 수 있어요.\n\n아세트아미노펜이 들어간 다른 약(종합감기약, 판콜에이, 타이레놀콜드 등)과 함께 복용하면 하루 허용량을 초과할 수 있어요. 성분표에 '아세트아미노펜' 또는 'Acetaminophen'이 있으면 중복 복용이 돼요. 바르비탈계 약물이나 삼환계 항우울제를 복용 중이라면 반드시 의사나 약사에게 미리 알려야 해요.",
