            "실온 보관, 어린이 손이 닿지 않는 곳이에요.\n\n습기가 많은 욕실이나 직사광선이 드는 창가는 피하세요. 알약이 습기를 흡수하면 코팅이 녹아 변질될 수 있어요. 개봉 후엔 병뚜껑을 단단히 닫고 유통기한 안에 사용하세요. 냉장 보관은 권장하지 않아요. 냉장고 안팎으로 온도 변화가 생기면 약에 물방울이 맺혀 오히려 습기를 더 많이 흡수해요.\n\n알약 색이 변하거나 이상한 냄새가 나면 복용하지 마세요. 유통기한이 지난 약은 약국이나 편의점의 폐의약품 수거함에 버려야 해요. 변기나 싱크대에 버리면 수질 오염이 생겨요.\n\n여행 시에는 원래 포장 그대로 휴대하고, 여름철 차 안처럼 온도가 높은 곳에 장시간 두지 마세요. 복용하고 남은 알약은 다른 용기나 약봉투에 옮겨 담지 말고 원래 병이나 시트 포장 그대로 두는 게 안전해요. 어린이가 사탕으로 오인할 수 있어서 반드시 어린이 손이 닿지 않는 잠금 서랍이나 높은 곳에 보관하세요.",
