            "파인큐나프록센현탁액은 나프록센 성분의 비스테로이드성 소염진통제예요. 식약처 허가사항에 따르면 관절이 붓고 아픈 류마티양 관절염, 퇴행성 변화로 오는 골관절염, 등뼈가 뻣뻣해지는 강직성 척추염에 쓸 수 있어요. 힘줄에 염증이 생긴 건염이나 급성 통풍 발작, 생리 때 겪는 월경곤란증에도 처방돼요.\n\n염좌나 타박상 같은 골격근장애, 수술 후나 발치 후 남는 통증, 편두통에도 적응증이 있어요. 정제나 캡슐을 삼키기 어려운 분들을 위한 현탁액 제형이라는 점이 다른 나프록센 제품과 다른 부분이죠. 복용은 간편해요. 흔들어서 복용하는 액상이라 흡수가 고르게 이뤄져요. 다만 원인을 없애는 치료제는 아니고, 증상을 가라앉히는 대증요법용이라는 점은 기억해두세요.",
