            "아나프록스정은 나프록센나트륨 성분의 비스테로이드성 소염진통제예요. 흔히 NSAID라고 부르는 계열이죠. 통증과 염증을 함께 잡아주는 게 특징이에요.\n\n식약처 등록 정보를 보면 적응증이 꽤 넓어요. 류마티양 관절염, 골관절염, 강직성 척추염 같은 관절 질환부터 급성통풍, 월경곤란증, 편두통, 발치 후 통증, 근육 삠·타박상, 허리통증까지 쓰여요. 생리통에 해당하는 월경곤란증이 정식 적응증에 들어 있다는 점이 이 약을 찾는 분들에게 중요한 포인트예요. 염증이 얽힌 통증에 특히 자주 선택돼요. 제조사는 종근당이고, 식약처 품목번호 198300064로 등록된 전문 소염진통제예요.",
