          content:
            "복용법은 간단해요. 성인은 1회 1캡슐(300mg)씩 1일 2~4회 먹고, 하루 최대 4캡슐(1,200mg)을 넘기지 않는 게 원칙이에요. 통증·염증 정도에 따라 횟수를 조절하되, 정해진 한도 안에서 써요. 급성질환에 오래 먹어야 할 때도 원칙적으로 5일 이내로 제한해요.\n\n술과는 거리를 두는 게 좋아요. 매일 세 잔 이상 정기적으로 마시는 분이 이 약이나 다른 해열진통제를 같이 쓰면 위장출혈 위험이 올라가거든요. 복용 뒤 어지러움이나 피로가 올 수 있어 운전·기계조작 전엔 몸 상태를 한번 살펴요. 보관은 습기와 빛을 피해 실온에 두고 어린이 손이 닿지 않는 곳에 두는 게 식약처 허가사항에 명시된 기본 수칙이에요.",
